using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"/posts/{id}");
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var root = doc.RootElement;

        return $"Title: {root.GetProperty("title").GetString()}\n\n{root.GetProperty("body").GetString()}";
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a summarization prompt for the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int maxSentences = 3)
    {
        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock(
                    $"Summarize the following text in at most {maxSentences} sentences. " +
                    $"Be concise and capture the key points.\n\n{text}")
            }
        ];
    }
}

